using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Diagnostics;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Collections.Generic;
public static class DownloadNames {
 public static string Clean(string value,int limit=160){value=Regex.Replace(value??"",@"[\x00-\x1F<>:""/\\|?*]"," ");value=Regex.Replace(value,@"\s+"," ").Trim(' ','.');if(value.Length>limit){value=value.Substring(0,limit).TrimEnd();if(value.Length>0&&char.IsHighSurrogate(value[value.Length-1]))value=value.Substring(0,value.Length-1);}if(value.Length==0)value="Download";if(Regex.IsMatch(value,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)",RegexOptions.IgnoreCase))value="_"+value;return value;}
 public static string FileName(string name){name=Clean(name,int.MaxValue);string cleaned=Clean(name);string ext=Path.GetExtension(name??"");if(name!=null&&name.Length>160&&ext.Length>0&&ext.Length<16){string stem=Clean(Path.GetFileNameWithoutExtension(name));stem=stem.Substring(0,Math.Min(stem.Length,160-ext.Length));if(stem.Length>0&&char.IsHighSurrogate(stem[stem.Length-1]))stem=stem.Substring(0,stem.Length-1);cleaned=stem+"."+Clean(ext.TrimStart('.'));}return cleaned;}
 public static string MediaName(string title,bool audio,bool clip,double start,double end){title=Clean(title);string ext=Path.GetExtension(title??"").ToLowerInvariant();if(new[]{".mp4",".webm",".mkv",".mp3",".m4a",".mov"}.Contains(ext))title=title.Substring(0,title.Length-ext.Length);string range=clip?" ["+TimeSpan.FromSeconds(start).ToString(@"hh\-mm\-ss")+" a "+TimeSpan.FromSeconds(end).ToString(@"hh\-mm\-ss")+"]":"";return Clean(title)+range+(audio?".mp3":".mp4");}
 public static string Unique(string folder,string filename){string stem=Path.GetFileNameWithoutExtension(filename),ext=Path.GetExtension(filename);string result=filename;for(int n=2;File.Exists(Path.Combine(folder,result));n++)result=stem+" ("+n+")"+ext;return result;}
 public static string Title(string json){var data=new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Deserialize<Dictionary<string,object>>(json);object title;if(data!=null&&data.TryGetValue("title",out title)&&title is string&&!string.IsNullOrWhiteSpace((string)title))return (string)title;return null;}
 static string Fallback(string link,bool video){var uri=new Uri(link);string name=Uri.UnescapeDataString(uri.Segments.LastOrDefault()??"").Trim('/');if(video||string.IsNullOrWhiteSpace(name)){string id=Regex.Match(uri.Query,@"(?:[?&])v=([^&]+)").Groups[1].Value;if(id.Length>0)name=Uri.UnescapeDataString(id);if(name.Length>50)name=name.Substring(0,50);name=uri.Host.Replace("www.","")+(name.Length>0?" - "+name:video?" - Vídeo":" - Arquivo");}return video?Clean(name):name;}
 public static async Task<string> Suggest(string link,bool video,bool audio,bool clip,double start,double end,CancellationToken ct,string tools=null){Engine.Validate(link);string name=null;using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(ct)){deadline.CancelAfter(video?15000:6000);try{if(video){tools=tools??Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tools");string exe=Path.Combine(tools,"yt-dlp.exe");if(File.Exists(exe)){name=await Task.Run(()=>ReadTitle(exe,tools,link,deadline.Token),deadline.Token);}}else{using(var request=new HttpRequestMessage(HttpMethod.Get,link)){request.Headers.Range=new System.Net.Http.Headers.RangeHeaderValue(0,0);using(var response=await Engine.Http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,deadline.Token)){var disposition=response.Content.Headers.ContentDisposition;if(response.IsSuccessStatusCode&&disposition!=null)name=(disposition.FileNameStar??disposition.FileName??"").Trim('"');}}}}catch(OperationCanceledException){ct.ThrowIfCancellationRequested();}catch{ct.ThrowIfCancellationRequested();}}ct.ThrowIfCancellationRequested();if(string.IsNullOrWhiteSpace(name))name=Fallback(link,video);return video?MediaName(name,audio,clip,start,end):FileName(name);}
 static string ReadTitle(string exe,string tools,string link,CancellationToken ct){ct.ThrowIfCancellationRequested();using(var p=new Process()){p.StartInfo=new ProcessStartInfo(exe,"--ignore-config --no-playlist --skip-download --dump-single-json --no-warnings --socket-timeout 8 --retries 0 --extractor-retries 0 --js-runtimes "+Engine.Quote("deno:"+Path.Combine(tools,"deno.exe"))+" -- "+Engine.Quote(link)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};var output=new StringBuilder();bool overflow=false;p.OutputDataReceived+=delegate(object sender,DataReceivedEventArgs e){if(e.Data==null)return;lock(output){if(output.Length+e.Data.Length<8*1024*1024)output.AppendLine(e.Data);else overflow=true;}};p.ErrorDataReceived+=delegate{};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();using(ct.Register(delegate{try{p.Kill();}catch{}})){p.WaitForExit();}ct.ThrowIfCancellationRequested();return p.ExitCode==0&&!overflow?Title(output.ToString()):null;}}
}



